from __future__ import annotations
import argparse, json, pathlib, shlex
from collections.abc import Mapping
from tools.mir_executor.local_hooks import local_config
_INSTRUCTIONS = {}
"""DispatchBrief contract for execution-lane handoff and durable resume."""


from pathlib import PurePosixPath

from pydantic import BaseModel, ConfigDict, Field, model_validator

_ID_PATTERN = r"^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$"


class DispatchBriefSourceRefs(BaseModel):
    """Source references used to derive a dispatch brief."""

    model_config = ConfigDict(extra="forbid", frozen=True)

    task_spec: str = Field(min_length=1)
    plan: str = Field(default="tasks/plan.md")
    phase: str = Field(min_length=1)


class DispatchBrief(BaseModel):
    """Execution-ready handoff artifact for one target agent and one slice."""

    model_config = ConfigDict(extra="forbid", frozen=True)

    version: int = Field(default=1)
    task_id: str = Field(min_length=1, pattern=_ID_PATTERN)
    phase_id: str | None = Field(default=None, pattern=_ID_PATTERN)
    slice_id: str = Field(min_length=1, pattern=_ID_PATTERN)
    target_agent: str = Field(min_length=1, pattern=_ID_PATTERN)
    user_intent: str = Field(min_length=1)
    expanded_goal: str = Field(min_length=1)
    owned_scope: tuple[str, ...] = Field(min_length=1)
    out_of_scope: tuple[str, ...] = ()
    verification_commands: tuple[str, ...] = Field(min_length=1)
    stop_conditions: tuple[str, ...] = Field(min_length=1)
    handoff_refs: tuple[str, ...] = ()
    tdd_change_refs: tuple[str, ...] = ()
    resume_state_ref: str = Field(min_length=1)
    source_refs: DispatchBriefSourceRefs

    @model_validator(mode="after")
    def _validate_contract(self) -> DispatchBrief:
        if self.version != 1:
            raise ValueError("DispatchBrief.version must be 1")
        expected_resume_ref = f"tasks/dispatch/{self.task_id}/{self.slice_id}.json"
        if self.resume_state_ref != expected_resume_ref:
            raise ValueError(
                "DispatchBrief.resume_state_ref must match "
                f"{expected_resume_ref!r}"
            )
        if self.source_refs.plan != "tasks/plan.md":
            raise ValueError("DispatchBrief.source_refs.plan must be 'tasks/plan.md'")
        for field_name in (
            "owned_scope",
            "out_of_scope",
            "verification_commands",
            "stop_conditions",
            "handoff_refs",
            "tdd_change_refs",
        ):
            values = getattr(self, field_name)
            if len(values) != len(set(values)):
                raise ValueError(f"DispatchBrief.{field_name} must not contain duplicates")
            if any(not value.strip() for value in values):
                raise ValueError(f"DispatchBrief.{field_name} values must be non-empty")
        for scope in self.owned_scope:
            if scope == "<unspecified>":
                continue
            _validate_relative_ref(scope.removesuffix("/**"), "owned_scope")
        _validate_relative_ref(self.resume_state_ref, "resume_state_ref")
        for ref in self.handoff_refs:
            _validate_relative_ref(ref, "handoff_refs")
        for ref in self.tdd_change_refs:
            if not ref.startswith("tasks/tdd.json#") or not ref.removeprefix(
                "tasks/tdd.json#"
            ):
                raise ValueError(
                    "DispatchBrief.tdd_change_refs must use tasks/tdd.json#<change_id>"
                )
        return self


def _validate_relative_ref(value: str, field_name: str) -> None:
    path = PurePosixPath(value)
    if path.is_absolute() or ".." in path.parts or "." in path.parts or "\\" in value:
        raise ValueError(f"DispatchBrief.{field_name} must be a confined relative path")

def load_dispatch_brief(path: pathlib.Path) -> DispatchBrief:
    """Load and validate a persisted DispatchBrief JSON file."""
    payload: dict[str, Any] = json.loads(path.read_text(encoding="utf-8"))
    return DispatchBrief(**payload)
def validate_brief(brief: pathlib.Path | str, repo_root: pathlib.Path):
    """Keep the typed DispatchBrief file schema while accepting plain prompts."""
    if isinstance(brief, pathlib.Path):
        from mir.core.conductor.dispatch_brief import load_dispatch_brief  # noqa: PLC0415

        return load_dispatch_brief(brief)
    return None

def pre_execute(args: argparse.Namespace, repo_root: pathlib.Path) -> None:
    """Resolve --family, map verifier strings and bind the brief to runtime inputs."""
    _resolve_family(args)
    root = pathlib.Path(args.repo_root).resolve()
    _map_verify_commands(args, root)
    brief_arg = getattr(args, "dispatch_brief", None)
    if not getattr(args, "dispatch", False) or brief_arg is None:
        return
    brief_path = pathlib.Path(brief_arg).resolve()
    try:
        brief = validate_brief(brief_path, root)
        _validate_dispatch_brief_execution(
            brief_path=brief_path,
            brief=brief,
            repo_root=root,
            change_id=args.change_id,
            allow_paths=getattr(args, "allow_paths", None) or [],
            verify_cmds=getattr(args, "verify_cmds", None) or [],
            verifiers=local_config(root).get("verifiers", {}),
        )
    except (OSError, ValueError) as exc:
        raise ValueError(f"DispatchBrief error: {exc}") from exc
    _INSTRUCTIONS[brief_path] = _active_instruction(args, brief)

def render_brief(validated, repo_root: pathlib.Path) -> str | None:
    """Render the complete typed brief plus the active loop-step instruction."""
    if validated is None:
        return None
    brief_path = (pathlib.Path(repo_root) / validated.resume_state_ref).resolve()
    instruction = _INSTRUCTIONS.pop(brief_path, validated.expanded_goal)
    payload = json.dumps(validated.model_dump(mode="json"), ensure_ascii=False, indent=2)
    return (
        "# DispatchBrief\n\n"
        f"Target profile: `{validated.target_agent}`\n\n"
        "## Active step instruction\n\n"
        f"{instruction.strip()}\n\n"
        "## Typed execution contract\n\n"
        f"```json\n{payload}\n```\n"
    )

def _resolve_family(args: argparse.Namespace) -> None:
    """Select the repo root registered for --family (profile_compiler registry)."""
    family = getattr(args, "family", None)
    if family is None:
        return
    from tools.profile_compiler.cli import resolve_family_path  # noqa: PLC0415

    try:
        family_root = resolve_family_path(family).resolve()
    except KeyError as exc:
        raise ValueError(f"Unknown family slug: {family!r}. {exc}") from exc
    requested = pathlib.Path(args.repo_root).resolve()
    # The common --repo-root defaults to cwd, so only another explicit root conflicts.
    if requested not in (pathlib.Path.cwd().resolve(), family_root):
        raise ValueError(f"--family {family!r} resolves to {family_root}, not {requested}")
    args.repo_root = family_root

def _map_verify_commands(args: argparse.Namespace, repo_root: pathlib.Path) -> None:
    """Map a command string equal to a registered verifier argv onto its ID.

    `scripts/loop_driver.sh` passes `tasks/tdd.json` command strings. Only exact
    argv matches are mapped; anything else stays and the merge gate rejects it.
    """
    commands = getattr(args, "verify_cmds", None)
    if not commands:
        return
    verifiers = local_config(repo_root).get("verifiers", {})
    by_argv = {tuple(argv): verifier_id for verifier_id, argv in verifiers.items()}
    args.verify_cmds = [
        command if command in verifiers else by_argv.get(_argv(command), command)
        for command in commands
    ]

def _argv(command: str) -> tuple[str, ...] | None:
    try:
        return tuple(shlex.split(command))
    except ValueError:
        return None

def _scope_covers(owned_scope: str, requested_path: str) -> bool:
    owned = owned_scope.removeprefix("./").rstrip("/")
    requested = requested_path.removeprefix("./").rstrip("/")
    if owned.endswith("/**"):
        prefix = owned.removesuffix("/**")
        return requested == prefix or requested.startswith(prefix + "/")
    return requested == owned or requested.startswith(owned + "/")

def _validate_dispatch_brief_execution(
    *,
    brief_path: pathlib.Path,
    brief,
    repo_root: pathlib.Path,
    change_id: str | None,
    allow_paths: list[str],
    verify_cmds: list[str],
    verifiers: Mapping[str, list[str]] | None = None,
) -> None:
    """Bind execution profile, scope, TDD ref, resume path, and merge checks."""
    expected_path = (repo_root / brief.resume_state_ref).resolve()
    if brief_path.resolve() != expected_path:
        raise ValueError("DispatchBrief path must match its resume_state_ref")
    profile_path = repo_root / ".claude" / "agents" / f"{brief.target_agent}.md"
    if not profile_path.is_file():
        raise ValueError(f"DispatchBrief target_agent profile is missing: {brief.target_agent}")
    if change_id is not None and f"tasks/tdd.json#{change_id}" not in brief.tdd_change_refs:
        raise ValueError("DispatchBrief does not bind the requested TDD change")
    for requested in allow_paths:
        if not any(_scope_covers(owned, requested) for owned in brief.owned_scope):
            raise ValueError(f"allow path is outside DispatchBrief owned_scope: {requested}")
    declared_argv = {_argv(command) for command in brief.verification_commands}
    verifiers = verifiers or {}
    undeclared_verifiers = [
        command
        for command in verify_cmds
        if command not in brief.verification_commands
        and (command not in verifiers or tuple(verifiers[command]) not in declared_argv)
    ]
    if undeclared_verifiers:
        raise ValueError(
            "verification command is not declared by DispatchBrief: "
            + ", ".join(undeclared_verifiers)
        )

def _active_instruction(args: argparse.Namespace, brief) -> str:
    """Return the prompt the common handler will send, as the fork rendered it."""
    from tools.mir_executor import cli  # noqa: PLC0415

    resume_job_id = getattr(args, "resume_job_id", None)
    if resume_job_id:
        from tools.mir_executor.jobs import JobRegistry  # noqa: PLC0415

        registry = JobRegistry(pathlib.Path(args.jobs_db))
        try:
            job = registry.get(resume_job_id)
        finally:
            registry.close()
        codex_args = list(job.codex_args) if job is not None else []
    else:
        codex_args = cli._resolve_execute_codex_args(args)
    return cli._prompt_from_codex_args(codex_args) or brief.expanded_goal.strip()
import sys, types
_loader = types.ModuleType("mir.core.conductor.dispatch_brief")
_loader.load_dispatch_brief = load_dispatch_brief
sys.modules[_loader.__name__] = _loader
